public sealed class D2DungeonSet
{
    public D2DungeonSet(int index, int act, bool pinned, bool isCow,
                        bool cowEligible, string name, int[] zones)
    {
        Index = index; Act = act; Pinned = pinned;
        IsCow = isCow; CowEligible = cowEligible; Name = name; Zones = zones;
    }

    public int Index { get; }
    // 1-5. Pool A is acts 1+2, pool B is acts 3+4+5 — see ApplyEntranceShuffle.
    public int Act { get; }
    // DS_FLAG_NO_SHUFFLE: stays where it is.
    public bool Pinned { get; }
    // The cow portal itself, and the sets it may be paired with.
    // is pre-placed before pool B is permuted, so it must be reproduced first.
    public bool IsCow { get; }
    public bool CowEligible { get; }
    public string Name { get; }
    public int[] Zones { get; }
}
